import 'dart:convert';
import 'dart:io' show File;
import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:url_launcher/url_launcher.dart';

void main() => runApp(const He3amApp());

class Track {
  String title, artist, link;
  bool favorite;
  List<String> tags;
  Track({required this.title, required this.artist, this.link = '', this.favorite = false, this.tags = const []});
  Map<String,dynamic> toJson()=>{'title':title,'artist':artist,'link':link,'favorite':favorite,'tags':tags};
  factory Track.fromJson(Map<String,dynamic> j)=>Track(title:j['title']??'',artist:j['artist']??'',link:j['link']??'',favorite:j['favorite']??false,tags:List<String>.from(j['tags']??[]));
}
class Playlist {
  String name;
  List<Track> tracks;
  Playlist(this.name,[this.tracks=const []]);
  Map<String,dynamic> toJson()=>{'name':name,'tracks':tracks.map((e)=>e.toJson()).toList()};
  factory Playlist.fromJson(Map<String,dynamic> j)=>Playlist(j['name']??'Playlist',List<Map<String,dynamic>>.from(j['tracks']??[]).map(Track.fromJson).toList());
}

class He3amApp extends StatefulWidget { const He3amApp({super.key}); @override State<He3amApp> createState()=>_He3amAppState(); }
class _He3amAppState extends State<He3amApp> {
  List<Playlist> lists=[]; int selected=0; bool dark=true; String query='';
  @override void initState(){super.initState(); _load();}
  Future<void> _load() async { final p=await SharedPreferences.getInstance(); final raw=p.getString('data'); setState(() {dark=p.getBool('dark')??true; if(raw!=null){lists=List<Map<String,dynamic>>.from(jsonDecode(raw)).map(Playlist.fromJson).toList();} if(lists.isEmpty)lists=[Playlist('My Music')];}); }
  Future<void> _save() async {final p=await SharedPreferences.getInstance(); await p.setString('data',jsonEncode(lists.map((e)=>e.toJson()).toList())); await p.setBool('dark',dark);}
  void refresh(){setState((){});_save();}
  Future<void> addPlaylist() async {final c=TextEditingController(); final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('New playlist'),content:TextField(controller:c,autofocus:true,decoration:const InputDecoration(hintText:'Playlist name')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Create'))])); if(ok==true&&c.text.trim().isNotEmpty){lists.add(Playlist(c.text.trim()));selected=lists.length-1;refresh();}}
  Future<void> addTrack({Track? edit,int? index}) async {final a=TextEditingController(text:edit?.artist), t=TextEditingController(text:edit?.title), l=TextEditingController(text:edit?.link), tags=TextEditingController(text:edit?.tags.join(', ')); final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:Text(edit==null?'Add track':'Edit track'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:a,decoration:const InputDecoration(labelText:'Artist')),TextField(controller:t,decoration:const InputDecoration(labelText:'Song')),TextField(controller:l,decoration:const InputDecoration(labelText:'Link (optional)')),TextField(controller:tags,decoration:const InputDecoration(labelText:'Tags (comma separated)'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Save'))])); if(ok==true&&a.text.trim().isNotEmpty&&t.text.trim().isNotEmpty){final tr=Track(artist:a.text.trim(),title:t.text.trim(),link:l.text.trim(),favorite:edit?.favorite??false,tags:tags.text.split(',').map((x)=>x.trim()).where((x)=>x.isNotEmpty).toList()); if(edit==null)lists[selected].tracks.add(tr); else lists[selected].tracks[index!]=tr; refresh();}}
  Future<void> importText() async {final c=TextEditingController(); final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Import tracks'),content:SizedBox(width:500,child:TextField(controller:c,maxLines:12,decoration:const InputDecoration(hintText:'Artist - Song\nArtist - Song'))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Import'))])); if(ok==true){for(final line in c.text.split('\n')){final s=line.trim(); final i=s.indexOf(' - '); if(i>0&&i<s.length-3)lists[selected].tracks.add(Track(artist:s.substring(0,i).trim(),title:s.substring(i+3).trim()));}refresh();}}
  Future<void> backup() async {final data=jsonEncode(lists.map((e)=>e.toJson()).toList()); final path=await FilePicker.platform.saveFile(dialogTitle:'Export HE3AM backup',fileName:'he3am_music_backup.json',bytes:utf8.encode(data)); if(path!=null && !path.startsWith('blob:')) await File(path).writeAsString(data);}
  Future<void> restore() async {final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true); if(r==null)return; final bytes=r.files.single.bytes; if(bytes==null)return; try{lists=List<Map<String,dynamic>>.from(jsonDecode(utf8.decode(bytes))).map(Playlist.fromJson).toList();selected=0;refresh();}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Invalid backup file')));}}
  Future<void> openLink(String x) async {final u=Uri.tryParse(x);if(u!=null)await launchUrl(u,mode:LaunchMode.externalApplication);}
  @override Widget build(BuildContext context){final theme=ThemeData(useMaterial3:true,brightness:dark?Brightness.dark:Brightness.light,colorSchemeSeed:Colors.deepPurple); final pl=lists[selected]; final shown=pl.tracks.where((x)=>('${x.artist} ${x.title} ${x.tags.join(' ')}').toLowerCase().contains(query.toLowerCase())).toList(); return MaterialApp(debugShowCheckedModeBanner:false,theme:theme,home:Scaffold(appBar:AppBar(title:const Text('HE3AM Music Hub',style:TextStyle(fontWeight:FontWeight.bold)),actions:[IconButton(tooltip:'Light / dark',onPressed:(){dark=!dark;refresh();},icon:Icon(dark?Icons.light_mode:Icons.dark_mode)),PopupMenuButton<String>(onSelected:(v){if(v=='import')importText();if(v=='backup')backup();if(v=='restore')restore();},itemBuilder:(_)=>const [PopupMenuItem(value:'import',child:Text('Import Artist - Song')),PopupMenuItem(value:'backup',child:Text('Export backup')),PopupMenuItem(value:'restore',child:Text('Restore backup'))])]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>addTrack(),icon:const Icon(Icons.add),label:const Text('Add song')),body:Row(children:[NavigationRail(selectedIndex:selected,onDestinationSelected:(i){setState(()=>selected=i);},labelType:NavigationRailLabelType.all,destinations:[...lists.asMap().entries.map((e)=>NavigationRailDestination(icon:const Icon(Icons.queue_music),label:Text(e.value.name))),const NavigationRailDestination(icon:Icon(Icons.add),label:Text('New'))]),Expanded(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(pl.name,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),IconButton(onPressed:addPlaylist,icon:const Icon(Icons.playlist_add))]),const SizedBox(height:12),TextField(onChanged:(x)=>setState(()=>query=x),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'Search songs, artists or tags',filled:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none))),const SizedBox(height:12),Expanded(child:shown.isEmpty?const Center(child:Text('No songs yet. Add one or import a list.')):ReorderableListView.builder(itemCount:shown.length,onReorder:(oldI,newI){if(newI>oldI)newI--;final item=shown.removeAt(oldI);shown.insert(newI,item);pl.tracks=shown;refresh();},itemBuilder:(_,i){final x=shown[i];return Card(key:ValueKey(x),child:ListTile(leading:CircleAvatar(child:Text(x.artist.isEmpty?'?':x.artist[0].toUpperCase())),title:Text(x.title,style:const TextStyle(fontWeight:FontWeight.w600)),subtitle:Text('${x.artist}${x.tags.isEmpty?'':'  •  '+x.tags.join(' • ')}'),trailing:Wrap(children:[IconButton(onPressed:(){x.favorite=!x.favorite;refresh();},icon:Icon(x.favorite?Icons.favorite:Icons.favorite_border)),if(x.link.isNotEmpty)IconButton(onPressed:()=>openLink(x.link),icon:const Icon(Icons.open_in_new)),IconButton(onPressed:()=>addTrack(edit:x,index:pl.tracks.indexOf(x)),icon:const Icon(Icons.edit)),IconButton(onPressed:(){pl.tracks.remove(x);refresh();},icon:const Icon(Icons.delete_outline))])));}))) ]))) ])));}
}
